head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;
scwin.gMktTp;
scwin.vScrenID = "ULDSTF30601_BOND.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_MARKET_FLAG, scwin.gLdMktTp);
    var ISUR_CD = $c.stf.getQuery(frame.srcUrl, "ISUR_CD"); // 다른 페이지(기업정보조회)에서 넘어오는 경우 처리.
    //alert(frame.srcUrl);
    $c.stf.setObjectValue(txb_ISUR_CD, ISUR_CD);
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");

    //alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};
scwin.fn_GetParentValue = function() {
    var pvd = scwin.fn_GetProvider();
    if (pvd != null) {
        scwin.gMktTp = pvd.scwin.gMktTp;
        scwin.gIsurCd = pvd.scwin.gIsurCd;
        if ($c.ut.trim(scwin.gIsurCd).length == 5) {
            scwin.fn_InitSearch();
        }
    }
};
scwin.fn_Search = function() {
    var vMARKET_FLAG = $c.stf.getObjectValue(rdo_MARKET_FLAG);
    var vISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    var vLIST_STATUS = $c.stf.getObjectValue(cmb_LIST_STATUS);
    var vISU_MKTP_TP_CD = $c.stf.getObjectValue(cmb_ISU_MKTP_TP_CD); //시장구분

    if (js_market == '9') {
        //관리자이면 채권팀으로 셋팅
        scwin.gDepCd = '2430';
    }
    var url = "/ListedCompany.do?method=listChargeIssue";
    url += "&MARKET_FLAG=" + vISU_MKTP_TP_CD;
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&EMP_NO=" + scwin.gEmpNo;
    url += "&ATTR_TP_CD=''";
    url += "&LIST_STATUS=" + vLIST_STATUS;
    url += "&SECU_GRP_ID=";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_List);
    if (dts_Grid.getTotalRow() > 0) {
        scwin.fn_readChargeIssue(grd_List, 1, "ISUR_CD");
    } else {
        dts_Corp_Info.removeAll();
        dts_Krx_Emp_Info.removeAll();
        dts_Charge1_Info.removeAll();
        dts_Charge2_Info.removeAll();
        dts_Charge3_Info.removeAll();
    }
};



// 다른창에서 담당종목 조회를 클릭할때
scwin.fn_InitSearch = function() {
    scwin.fn_getChargeIssue(scwin.gIsurCd, scwin.gMktTp);
};
scwin.fn_readChargeIssue = function(GridID, row, colid) {
    if (row < 1) return;
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    var vMKT_TP_CD = objDataID.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD");
    scwin.fn_getChargeIssue(vISUR_CD, vMKT_TP_CD);
};
scwin.fn_getChargeIssue = function(vISUR_CD, vMKT_TP_CD) {
    scwin.fn_HideCorpEmpLabels(vMKT_TP_CD); //코스닥 숨기기.

    var url = "/ListedCompany.do?method=readChargeIssue&Flag=1&ISUR_CD=" + vISUR_CD + "&BOND_YN=Y";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //var url = "/ListedCompany.do?method=readChargeIssue&Flag=9&ISUR_CD=" + vISUR_CD;
    // 회사정보
    dts_Corp_Info.DataID = encodeURI(url);
    dts_Corp_Info.Reset();

    //상공부 담당자 정보
    url = "/ListedCompany.do?method=readChargeIssue&Flag=2&ISUR_CD=" + vISUR_CD + "&BOND_YN=Y";
    dts_Krx_Emp_Info.DataID = encodeURI(url);
    dts_Krx_Emp_Info.Reset();

    // 공시책임자(유, 코)
    url = "/ListedCompany.do?method=readChargeIssue&Flag=7&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=4&BOND_YN=Y";
    dts_Charge1_Info.DataID = encodeURI(url);
    dts_Charge1_Info.Reset();

    // 공시담당자1, 공시담당자(유, 코)
    url = "/ListedCompany.do?method=readChargeIssue&Flag=8&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=4&BOND_YN=Y";
    dts_Charge2_Info.DataID = encodeURI(url);
    dts_Charge2_Info.Reset();

    // 공시담당자2, 공시실무자(유, 코)
    url = "/ListedCompany.do?method=readChargeIssue&Flag=9&ISUR_CD=" + vISUR_CD + "&MKT_TP_CD=4&BOND_YN=Y";
    dts_Charge3_Info.DataID = encodeURI(url);
    dts_Charge3_Info.Reset();
    var vStr = $c.stf.getObjectValue(txb_Corp_CAP);
    if (vStr != "") {
        vStr2 = $c.stf.FormatNumberEx(vStr);
        $c.stf.setObjectValue(txb_Corp_CAP, vStr2);
    }
};
scwin.fn_HideCorpEmpLabels = function(flag) {
    var vStockLabels = new Array(lbl_CorpEmp2, lbl_CorpEmp3);
    var vKosdaqLabels = new Array(lbl_CorpEmp2_1, lbl_CorpEmp3_1);
    // 유가는 초기값을 가지고 있으므로 위치 이동은 없다.
    if (flag == "1") {
        // 유가. => 코스닥 숨기고 유가 위치이동 및 보이기.

        for (var i = 0; i < vKosdaqLabels.length; i++) {
            $c.stf.showObj(vKosdaqLabels[i], false);
            $c.stf.showObj(vStockLabels[i], true);
        }
    } else if (flag == "2") {
        // 코스닥.=>유가를 숨기고 코스닥 위치이동 및 보이기
        for (var i = 0; i < vStockLabels.length; i++) {
            $c.stf.SetWindowPos(vKosdaqLabels[i], vStockLabels[i].style.top, vStockLabels[i].style.left, vStockLabels[i].style.getStyle("width"), vStockLabels[i].style.getStyle("height"));
            $c.stf.showObj(eval(vStockLabels[i]), false);
            $c.stf.showObj(vKosdaqLabels[i], true);
        }
    }
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_mkt, false);
    $c.stf.showObj(panel_debug, false);
    if (js_market == "1") {
        $c.stf.showObj(btn_Resume, true);
    } else {
        $c.stf.showObj(btn_Resume, false);
    }
};
scwin.fn_changeFormat = function() {
    var ar = new Array(txb_Corp_RGHT_LIST_DD, txb_Chrg1_CHRG_DESIGN_DD, txb_Chrg1_WORK_TM, txb_Chrg2_WORK_TM, txb_Chrg3_WORK_TM, txb_Chrg2_CHRG_DESIGN_DD, txb_Chrg3_CHRG_DESIGN_DD);
    for (var i = 0; i < ar.length; i++) {
        var bfVal = $c.stf.getObjectValue(ar[i]);
        if (bfVal != "") {
            var afVal = $c.stf.FormatDateEx(bfVal);
            //alert(bfVal + ", " + afVal);
            $c.stf.setObjectValue(ar[i], afVal);
        }
    }
};
scwin.fn_OpenResume = function() {
    $c.frame.path("../../").GWinOpen("ULDSTF30612", "/issueinfo/ULDSTF30612_BOND.gfm", "이력조회", 20, 20, 1270, 780, "");
};
scwin.FormatDateEx = function(str) {
    if (str == "") return "";
    return str.substring(0, 4) + "-" + str.substring(4, 6) + "-" + str.substring(6, 8);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_readChargeIssue(grd_List, row, colid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.rdo_MARKET_FLAG_OnSelChange = function() {
    scwin.fn_HideCorpEmpLabels($c.stf.getObjectValue(rdo_MARKET_FLAG));
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    scwin.fn_readChargeIssue(grd_List, 1, "ISUR_CD");
};
scwin.btn_ISUR_CD_onclick = function() {
    $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM); //2009.09.01 채권법인검색

};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.dts_Charge3_Info_OnLoadCompleted = function(rowcount) {
    scwin.fn_changeFormat();
};
scwin.btn_Excel_onclick = function() {
    if (grd_List2.getTotalRow() < 1) {
        $c.win.alert("저장할 정보가 없습니다.");
    } else {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_List2, "담당종목목록", "", "8");
    }
};
scwin.btn_Resume_onclick = function() {
    scwin.fn_OpenResume();
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_HideCorpEmpLabels("1"); //코스닥 숨기기.

    scwin.fn_GetParentValue();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    scwin.fn_Init();
    scwin.fn_Search();
};
